const getAudioPath = async (text, speed, dirPath, config) => {
  const http = require('http');
  const fs = require('fs');
  const path = require('path');
  const crypto = require('crypto');
  const child_process = require('child_process');

  const checkServer = () => new Promise((resolve) => {
    const req = http.get('http://127.0.0.1:8000/api/status', (res) => resolve(res.statusCode === 200));
    req.on('error', () => resolve(false));
  });

  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

  let isReady = await checkServer();
  if (!isReady) {
    console.log("TTS Server offline, starting...");
    const batPath = 'C:\\Tools\\Codes\\audiobook\\start_server.bat';
    const child = child_process.spawn('cmd.exe', ['/c', batPath], {
      detached: true,
      windowsHide: true,
      stdio: 'ignore',
      cwd: 'C:\\Tools\\Codes\\audiobook',
      env: Object.assign({}, process.env, { LAUNCHED_BY_KOODO: '1' })
    });
    child.unref();

    for (let i = 0; i < 30; i++) {
      await sleep(1000);
      if (await checkServer()) {
        isReady = true;
        break;
      }
    }
  }

  if (!isReady) {
    throw new Error('TTS Server failed to start after 30 seconds.');
  }

  return new Promise((resolve, reject) => {
    const postData = JSON.stringify({ text: text });
    const options = {
      hostname: '127.0.0.1',
      port: 8000,
      path: '/api/synthesize_text',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };
    const req = http.request(options, (res) => {
      if (res.statusCode !== 200) {
        return reject(new Error('TTS Server returned status code ' + res.statusCode));
      }
      const fileName = crypto.randomUUID() + '.wav';
      const filePath = path.join(dirPath, fileName);
      const fileStream = fs.createWriteStream(filePath);
      res.pipe(fileStream);

      fileStream.on('close', () => {
        resolve(filePath);
      });

      fileStream.on('error', (err) => {
        fs.unlink(filePath, () => {});
        reject(err);
      });
    });
    req.on('error', (e) => reject(e));
    req.write(postData);
    req.end();
  });
};
global.getAudioPath = getAudioPath;
